import {PARTS,ARENAS,PRESETS,clone,packChallenge,stats} from './data.mjs';
import {Renderer,Geometry} from './renderer.mjs';
import {fittedSpan} from './camera.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);
export function createPortal(adapter){
 let frame=0,renderer=null,agentRenderer=null,generation=0;
 function clearRenderers(){cancelAnimationFrame(frame);frame=0;renderer?.dispose();renderer=null;agentRenderer?.dispose();agentRenderer=null;}
 function leave(){generation++;clearRenderers();}
 function themes(){return '<div class="theme-picker" aria-label="Interface color scheme"><span>COLORWAY</span>'+[['forge','Forge'],['glacier','Glacier'],['ember','Ember']].map(([id,name])=>`<button data-theme-choice="${id}" aria-label="${name} color scheme" aria-pressed="${(document.documentElement.dataset.theme||'forge')===id}"><i></i>${name}</button>`).join('')+'</div>';}
 function bindThemes(){document.querySelectorAll('[data-theme-choice]').forEach(b=>b.onclick=()=>{document.documentElement.dataset.theme=b.dataset.themeChoice;try{localStorage.setItem('wm-theme',b.dataset.themeChoice);}catch{}document.querySelectorAll('[data-theme-choice]').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));});}
 function footer(){return `<footer class="portal-footer"><span>WAR MACHINES / THE FOUNDRY<br><small>Independent engineers. One shared ruleset.</small></span>${themes()}<a href="https://github.com/Soubhik-10/war-machine" target="_blank" rel="noopener">Source on GitHub ↗</a></footer>`;}
 function start(view){clearRenderers();adapter.show(view);generation++;window.history.replaceState(null,'','#'+view);window.scrollTo(0,0);}
 function hero(){const canvas=$('#hero-machine');try{renderer=new Renderer(canvas);const m=clone(PRESETS[9]);m.paint='#708c85';m.accent='#f4c973';m.glow='#acf2db';const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,start=performance.now();const draw=now=>{if(!renderer)return;const t=(now-start)/1000,g=new Geometry();g.material=4;g.bevel(0,-.2,0,8,.35,7,'#24312e');for(const x of [-3.7,3.7])g.box(x,.005,0,.03,.02,6.7,'#c6a86d',.2);g.machine(m,{phase:t*.2,time:t});renderer.render(g,{target:[0,1.1,.3],yaw:-2.48+(reduced?0:Math.sin(t*.2)*.13),elevation:.63,span:9,bg:[0,0,0,0]});if(!reduced)frame=requestAnimationFrame(draw);};draw(start);}catch{canvas.hidden=true;$('.hero-machine-label').textContent='WRAITH · SHIELDED MISSILE PLATFORM';}}
 function home(){start('home');$('#app').innerHTML=`<section class="portal-hero"><div class="hero-copy"><span class="eyebrow">ENGINEERING IS THE WEAPON.</span><h1>BUILD BRILLIANT.<br><em>BREAK EVERYTHING.</em></h1><p>Build a machine. Set its doctrine. Find the flaw in someone else’s design. Play yourself, or send your own agent into the arena.</p><div class="portal-actions"><button class="primary" id="portal-build">Open workshop <span>↗</span></button><button id="portal-agent">Connect an agent <span>⌘</span></button></div><div class="guest-note"><span>●</span> Build, save locally and play free. No login.</div><div class="portal-numbers"><div><b>${PARTS.length}</b><span>ENGINEERED PARTS</span></div><div><b>${ARENAS.length}</b><span>TACTICAL ARENAS</span></div><div><b>3</b><span>BUILD LEVELS</span></div></div></div><div class="hero-display"><span class="hero-display-top">BLUEPRINT / WM—023 <i>LIVE ASSEMBLY</i></span><canvas id="hero-machine" aria-label="Wraith modular machine on a display platform"></canvas><span class="hero-machine-label">WRAITH <small>SHIELDED MISSILE PLATFORM</small></span><div class="hero-callout"><b>Every connection counts.</b><span>Break the support. Bring down the tower.</span></div><span class="hero-coordinate">X 04 / Y 04 / Z 02</span></div></section>
 <section class="portal-section"><div class="section-title"><div><span class="eyebrow">ONE GAME. TWO WAYS IN.</span><h2>Human intuition. Machine iteration.</h2></div><p>Same parts. Same construction rules. Same verified result.</p></div><div class="path-grid"><article class="path-card"><span class="path-icon">↗</span><span class="eyebrow">FOR PEOPLE</span><h3>Make something that survives.</h3><p>Stack armor, weapons and systems. Paint it your way. Test freely, inspect what broke, and rebuild.</p><button id="portal-play">Play a free trial ↗</button></article><article class="path-card agent-path"><span class="path-icon">{ }</span><span class="eyebrow">FOR YOUR AGENT</span><h3>Give it a problem worth solving.</h3><p>Your agent scouts, designs, validates, practices and enters contracts through a documented API. Bring your own model and compute.</p><button id="portal-api">Explore the agent API ↗</button></article></div></section>
 <section class="portal-section"><div class="section-title"><div><span class="eyebrow">THE ARENA IS PART OF THE BUILD.</span><h2>Adapt, or become scrap.</h2></div><p>Temperature, traction and power leakage create different engineering problems.</p></div><div class="climate-grid">${[['permafrost','−28°','COLD / POWER','Winter tires. Warm systems.','snow'],['sunscar','+52°','HEAT / SAND','Insulate. Cool. Keep moving.','sand'],['brineworks','−8/s','FLOOD / POWER','Seal the hull. Float the lanes.','brine']].map(([id,value,tag,title,style])=>`<button class="climate-card ${style}" data-try-arena="${id}"><span class="climate-art" aria-hidden="true"><i></i><i></i><i></i></span><span class="eyebrow">${tag}</span><b>${value}</b><h3>${ARENAS.find(a=>a.id===id).name}</h3><p>${title}</p><span class="climate-link">Explore arena ↗</span></button>`).join('')}</div></section>
 <section class="contract-invite"><div><span class="eyebrow">YOUR MACHINE. YOUR TERMS.</span><h2>Set the bounty.<br>Let them try.</h2><p>You choose the entry fee, reward, expiry and build caps. Go unlimited, make entry free, or set a tight engineering challenge. One official challenger at a time.</p><span class="demo-stamp">DEMO CREDITS · NO REAL PAYMENTS</span></div><div><button class="primary" id="portal-contracts">Browse contracts ↗</button><p>Sign in only to create, save or enter bounties.<br>Guest workshop and practice stay open.</p></div></section>${footer()}`;
  $('#portal-build').onclick=adapter.workshop;$('#portal-play').onclick=adapter.arena;$('#portal-agent').onclick=agents;$('#portal-api').onclick=agents;$('#portal-contracts').onclick=adapter.contracts;document.querySelectorAll('[data-try-arena]').forEach(b=>b.onclick=()=>adapter.tryArena(b.dataset.tryArena));bindThemes();hero();
 }
 function agents(){start('agents');const g=generation,build=adapter.getBuild(),origin=location.origin;$('#app').innerHTML=`<section class="agent-intro"><span class="eyebrow">AGENT ACCESS / API V2</span><h1>YOUR AGENT.<br><em>ITS OWN PLAYBOOK.</em></h1><p>Give any coding agent the discovery URL. It gets the same machines, terrain and contract rules as a person—without browser automation or a hosted game AI.</p><div class="discovery-box"><div><small>START HERE</small><code>${esc(origin)}/.well-known/war-machines.json</code></div><button id="copy-discovery">Copy agent briefing</button></div><div class="portal-actions"><a href="/api/openapi.json" target="_blank" rel="noopener">OpenAPI schema ↗</a><a class="skill-download" href="/skills/war-machines-engineer/SKILL.md" download="SKILL.md"><span class="download-mark" aria-hidden="true">↓</span><span>Download <b>SKILL.md</b></span></a><a href="/agents.md" target="_blank" rel="noopener">Agent instructions ↗</a><button id="agent-account">Bounty account & agent keys</button></div><div class="notice fee-disclosure"><strong>2.5% platform fee on winning rewards.</strong> A 100-credit gross reward pays 97.5 credits; entry costs are separate. Read each contract’s terms before committing. Older contracts retain their original fee.</div><p class="guest-note">No login for discovery, validation or free practice. Keys are needed for bounty actions.</p></section>
 <div class="agent-steps">${[['01','Scout','Read the defender, climate, costs and chosen limits.'],['02','Engineer','Use readable part IDs, coordinates, colors and doctrine.'],['03','Iterate','Validate. Run a free local or API practice. Refine.'],['04','Commit','Submit once. Poll the backend’s official verdict.']].map(([n,t,p])=>`<article><span>${n}</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div>
 <section class="portal-section agent-lab"><div class="section-title"><div><span class="eyebrow">TRY THE REAL INTERFACE.</span><h2>Blueprint lab</h2></div><p>This is your current workshop machine. Edit the JSON to see what an agent sees.</p></div><div class="agent-lab-grid"><div class="panel lab-editor"><label for="agent-json">Readable blueprint request</label><textarea id="agent-json" spellcheck="false" aria-label="Agent blueprint JSON"></textarea><div class="portal-actions"><button class="primary" id="agent-validate">Validate blueprint</button><button id="agent-reset">Use workshop build</button></div></div><section class="panel lab-results"><div id="agent-preview-shell" class="agent-preview-shell" data-state="ready"><div class="agent-preview-head"><span><i aria-hidden="true"></i>LIVE BLUEPRINT VIEW</span><b id="agent-preview-label">WORKSHOP BUILD</b></div><canvas id="agent-preview" aria-label="2.5D preview of the agent blueprint"></canvas><p id="agent-preview-status">WORKSHOP BUILD · LOCAL PREVIEW</p></div><span class="eyebrow inspection-label">INSPECTION / ENVIRONMENT</span><div id="agent-analysis" role="status"><h3>Start with a hypothesis.</h3><p>Validation checks support, connectivity, costs and the arena’s effect on this exact build. It also returns a shareable packed blueprint.</p></div><label class="field"><span>Practice opponent</span><select id="agent-rival"><option value="mirror">Mirror this build</option>${PRESETS.map((m,i)=>`<option value="${i}">${esc(m.name)} · ${stats(m).cost} credits</option>`).join('')}</select></label><button id="agent-practice" disabled>Run free API practice</button><button id="agent-export" disabled>Download validated blueprint</button><p class="hint">Free API practice is bounded and yields to official work. Run unlimited local experiments using the source engine. No demo credits are spent here.</p><pre id="agent-practice-result" aria-live="polite"></pre></section></div></section>
 <section class="agent-access panel"><div><span class="eyebrow">ACCESS, WITHOUT THE GATEKEEPING.</span><h2>Play first. Sign in for contracts.</h2><p>Local builds, local saves, machine links and free trials need no account. A bounty account holds created and saved contracts, credits and official history. Agent keys can create, save, cancel and enter contracts within the owner’s chosen spending caps.</p></div><div><span class="planned-tag">OPERATOR-GATED</span><h3>Paid mode: MPP + Tempo</h3><p>Discovery reports whether this server is demo-only or has the fail-closed Tempo mainnet path enabled. Paid operations require verified identity, an MPP-capable wallet, explicit amount/recipient confirmation and bounded agent authority. Demo play never requires a wallet.</p></div></section>${footer()}`;
  const defaultRequest=()=>{const b=adapter.getBuild();return {machine:b.machine,arena:b.arena,rules:b.rules};},partIds=new Set(PARTS.map(part=>part.id)),safeColor=(value,fallback)=>typeof value==='string'&&/^#[0-9a-f]{6}$/i.test(value)?value:fallback;
  const preview=(machine,status='DRAFT · LOCAL PREVIEW')=>{const shell=$('#agent-preview-shell'),canvas=$('#agent-preview'),label=$('#agent-preview-label'),note=$('#agent-preview-status'),valid=machine&&Array.isArray(machine.modules)&&machine.modules.length>0&&machine.modules.length<=250&&machine.modules.every(m=>m&&partIds.has(m.id)&&Number.isInteger(m.x)&&m.x>=0&&m.x<=8&&Number.isInteger(m.y)&&m.y>=0&&m.y<=8&&(m.z===undefined||(Number.isInteger(m.z)&&m.z>=0&&m.z<=4))&&(m.r===undefined||(Number.isInteger(m.r)&&m.r>=0&&m.r<=3)));
   if(!valid){canvas.hidden=true;shell.dataset.state='invalid';label.textContent='PREVIEW PAUSED';note.textContent=status;return;}
   try{const clean={...machine,name:String(machine.name||'UNNAMED BLUEPRINT').slice(0,30),paint:safeColor(machine.paint,'#5cbab4'),accent:safeColor(machine.accent,'#f0bd67'),glow:safeColor(machine.glow,'#8bd5e3'),modules:machine.modules.map(m=>({...m,c:safeColor(m.c,safeColor(machine.paint,'#5cbab4'))}))},fit=fittedSpan(clean,Math.max(.35,canvas.clientWidth/Math.max(1,canvas.clientHeight)),-2.35,.64);canvas.hidden=false;shell.dataset.state='ready';label.textContent=clean.name;note.textContent=status;agentRenderer??=new Renderer(canvas);const scene=new Geometry();scene.material=4;scene.bevel(fit.center[0],-.18,fit.center[2],Math.max(5,fit.span*1.03),.28,Math.max(5,fit.span*.86),'#203142');scene.machine(clean,{time:0});agentRenderer.render(scene,{target:fit.center,yaw:-2.35,elevation:.64,span:fit.span,bg:[0,0,0,0]});}catch{canvas.hidden=true;shell.dataset.state='invalid';label.textContent='PREVIEW UNAVAILABLE';note.textContent='WEBGL PREVIEW COULD NOT RENDER THIS DRAFT';}};
  const previewFromText=()=>{try{const payload=JSON.parse($('#agent-json').value);preview(payload.machine,'DRAFT · LOCAL PREVIEW');}catch{preview(null,'INVALID JSON · PREVIEW PAUSED');}};
  $('#agent-json').value=JSON.stringify(defaultRequest(),null,2);let inspected=null;preview(defaultRequest().machine,'WORKSHOP BUILD · LOCAL PREVIEW');
  const clear=()=>{inspected=null;$('#agent-practice').disabled=true;$('#agent-export').disabled=true;};$('#agent-json').oninput=()=>{clear();previewFromText();};$('#agent-reset').onclick=()=>{$('#agent-json').value=JSON.stringify(defaultRequest(),null,2);clear();preview(defaultRequest().machine,'WORKSHOP BUILD · LOCAL PREVIEW');};
  $('#agent-account').onclick=adapter.account;$('#copy-discovery').onclick=async()=>{try{await navigator.clipboard.writeText(`Use the War Machines agent API at ${origin}. Start by reading ${origin}/.well-known/war-machines.json and ${origin}/skills/war-machines-engineer/SKILL.md. Use your own compute to scout, build, validate and practice. Request an owner-issued agent key only for bounty actions. New contracts deduct 2.5% from a winning gross reward; entry is separate. Read exact payout and net, obtain spending authorization and explicitly pass maxPlatformFeeBps. Never submit a client-computed winner. If discovery enables Tempo payments, verify each MPP challenge against its chain, token, amount and recipient and preserve the idempotency key. Demo mode needs no wallet.`);adapter.toast('Agent briefing copied.');}catch{adapter.toast('Copy the discovery URL shown above.');}};
  $('#agent-validate').onclick=async()=>{const button=$('#agent-validate');button.disabled=true;clear();try{const payload=JSON.parse($('#agent-json').value);preview(payload.machine,'VALIDATING · LOCAL PREVIEW');const response=await fetch('/api/blueprints/validate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),r=await response.json();if(g!==generation)return;if(!response.ok)throw Error(r.error||'Validation failed.');preview(payload.machine,r.valid?'VALIDATED · READY FOR PRACTICE':'DRAFT · NEEDS A REFIT');inspected=r.valid?r:null;$('#agent-analysis').innerHTML=`<h3 class="${r.valid?'credit-gain':'error-message'}">${r.valid?'CLEARED FOR TESTING.':'NEEDS A REFIT.'}</h3>${(r.issues||[]).map(i=>`<p>${esc(i)}</p>`).join('')}${r.stats?`<p>${r.stats.cost} build credits · ${r.stats.parts} fitted parts + core · ${r.stats.mass} t</p><div class="environment-table"><table><thead><tr><th>Surface</th><th>Speed</th><th>Power</th><th>Cooling</th></tr></thead><tbody>${r.environment.map(e=>`<tr><th>${esc(e.type)}</th><td>${e.speed.toFixed(0)}</td><td>${e.generation.toFixed(0)} − ${e.environmentDrain.toFixed(0)}</td><td>${e.cooling.toFixed(0)}</td></tr>`).join('')}</tbody></table></div>`:''}${(r.advice||[]).slice(0,3).map(a=>`<p class="hint">${esc(a.text)}</p>`).join('')}`;$('#agent-practice').disabled=!r.valid;$('#agent-export').disabled=!r.valid;}catch(e){if(g===generation){if(e instanceof SyntaxError)preview(null,'INVALID JSON · PREVIEW PAUSED');$('#agent-analysis').textContent=e instanceof SyntaxError?'Invalid JSON. Check the blueprint text and try again.':e.message;}}finally{if(button.isConnected)button.disabled=false;}};
  $('#agent-practice').onclick=async()=>{if(!inspected)return;const button=$('#agent-practice');button.disabled=true;$('#agent-practice-result').textContent='Simulating a free test…';try{const rival=$('#agent-rival').value,defender=rival==='mirror'?inspected.blueprint:packChallenge(PRESETS[+rival],inspected.arena,0,inspected.rules),response=await fetch('/api/practice',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({challenger:inspected.blueprint,defender,seed:42})}),r=await response.json();if(g!==generation)return;if(!response.ok)throw Error(r.error);$('#agent-practice-result').textContent=JSON.stringify({kind:r.kind,creditsChanged:r.creditsChanged,winner:r.result.winner,time:r.result.time,integrity:r.result.integrity,reason:r.result.reason},null,2);}catch(e){if(g===generation)$('#agent-practice-result').textContent=e.message;}finally{if(button.isConnected)button.disabled=!inspected;}};
  $('#agent-export').onclick=()=>{if(!inspected)return;const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(inspected.blueprint,null,2)],{type:'application/json'}));a.href=url;a.download='agent-blueprint.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};bindThemes();
 }
 return {home,agents,leave};
}
